The `validateFixtureCoverage` function maps over `frontendFixtures?.fixtures` and `frontendFixtureManifest?.fixture_manifest` without filtering out non-record entries first. Additionally, it does not record explicit invalid-type diagnostics if these fields are present but are not arrays.

To ensure the system fails closed gracefully, we should:
1. Filter out non-record entries before mapping.
2. Record explicit invalid-type diagnostics if the fields are present but are not arrays.

```javascript
function validateFixtureCoverage({
  handoff,
  frontendFixtures,
  frontendFixtureManifest,
  rehearsalReceipt,
  errors,
}) {
  const coverage = handoff?.fixture_coverage;
  const smokeChecklist = arrayFrom(handoff?.smoke_checklist).filter(isRecord);

  if (frontendFixtures?.fixtures && !Array.isArray(frontendFixtures.fixtures)) {
    errors.push('frontend_fixtures_fixtures_invalid_type');
  }
  if (frontendFixtureManifest?.fixture_manifest && !Array.isArray(frontendFixtureManifest.fixture_manifest)) {
    errors.push('frontend_fixture_manifest_fixture_manifest_invalid_type');
  }

  const fixtures = arrayFrom(frontendFixtures?.fixtures).filter(isRecord);
  const manifestEntries = arrayFrom(frontendFixtureManifest?.fixture_manifest).filter(isRecord);

  const fixtureIds = fixtures.map((fixture) => fixture.fixture_id);
  const manifestIds = manifestEntries.map((entry) => entry.fixture_id);

  const fixturesCoverRequired = REQUIRED_FIXTURE_IDS.every((id) => fixtureIds.includes(id));
  const manifestCoversRequired = REQUIRED_FIXTURE_IDS.every((id) => manifestIds.includes(id));
  const valid = coverage?.fixture_manifest_path === handoff?.artifact_paths?.fixture_manifest &&
    coverage?.fixture_count === REQUIRED_FIXTURE_IDS.length &&
    fixturesCoverRequired &&
    manifestCoversRequired &&
    smokeChecklist.length >= 9 &&
    rehearsalReceipt?.rehearsal_summary?.total_ms_reveal_payload_row_count === 3530 &&
    rehearsalReceipt?.resource_access_receipt?.pre_attempt_payload_asset_exposure_count === 0;
  if (!valid) errors.push('fixture_coverage_or_smoke_checklist_invalid');
  return valid;
}
```

